	encodedToken, err := tokenstore.Get(c.KeychainService, c.Handle)
	if err != nil {
		return "", fmt.Errorf("failed to get token from keyring: %w", err)
	}
	token, _ := tokenstore.DecodeTokenWithExpiration(encodedToken)
