// upserts a context entry in contexts.json (flipping current_context
// to it).
//
// contextName overrides the default context name; pass "" to derive
// from the issuer URL host (the common case).
func runInteractiveLogin(cmd *cobra.Command, cfg Config, contextName string) error {
	coreBaseURL, err := loginBaseURL(cfg)
	if err != nil {
		return err
	}
	result, err := clilogin.Run(cmd.Context(), clilogin.Options{
		CoreBaseURL: coreBaseURL,
		Browser: func(url string) error {
			openBrowser(url)
			return nil
		},
		Stdout: cmd.ErrOrStderr(),
	})
	if err != nil {
		return fmt.Errorf("login: %w", err)
	}

	expiresIn := result.ExpiresIn
	if expiresIn <= 0 {
		expiresIn = interactiveLoginFallbackTTL
	}
	// IssuerURL is where the JWT was actually minted (may differ from the
	// typed URL in cross-region flows). Both the keyring slot and the
	// context's KeychainService key off this trimmed URL so post-login
	// reads land on the same slot regardless of which URL is being
	// addressed in subsequent invocations.
	trimmedIssuer := strings.TrimRight(result.IssuerURL, "/")
	keychain := tokenstore.CoreKeyringService(trimmedIssuer)
	encoded := tokenstore.EncodeTokenWithExpiration(result.Token, expiresIn)
	if err := tokenstore.Set(keychain, result.Handle, encoded); err != nil {
		return fmt.Errorf("store access token: %w", err)
	}
	if result.RefreshToken != "" {
		if err := tokenstore.Set(keychain+":refresh", result.Handle, result.RefreshToken); err != nil {
			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not store refresh token: %v\n", err)
		}
	}

	configDir, err := entireConfigDir()
	if err != nil {
		return err
	}
	resolvedContext, err := upsertLoginContext(configDir, result.IssuerURL, result.Provider, result.Handle, contextName, cmd)
	if err != nil {
		return err
	}

	fmt.Fprintf(cmd.ErrOrStderr(), "Logged in as %s (%s) on %s\n", result.Handle, result.AccountID, result.IssuerURL)
	fmt.Fprintf(cmd.ErrOrStderr(), "Activated context %q — run 'entire-core context list' to see all contexts\n", resolvedContext)
	return nil
}

// upsertLoginContext writes the freshly-logged-in identity as a context
// in contexts.json and makes it the current context. Default name =
// <provider>:<handle>@<host> (falling back to bare host when provider
// or handle are empty); pass --name to override. The keychain slot is
// `entire-core:<issuer-url>` so storeCoreToken's earlier write and the
// post-login readers (readCoreToken, git-remote-entire) agree on where
// the token lives.
