// only way for `auth login` against a fresh core to actually take
// effect when another context already exists. Upsert alone wouldn't:
// it only seeds CurrentContext when previously empty.
//
// Runs under a single flock via contexts.Modify so a parallel git push
// triggering BindCluster can't race the upsert and silently lose its
// cluster→context binding between our load and our save.
func upsertLoginContext(configDir, issuerURL, provider, handle, contextName string, cmd *cobra.Command) (string, error) {
