//go:build ignore

// Command normalize rewrites the fetched Core API spec into a form the Go
// client generator (ogen) accepts.
//
// huma emits JSON-Schema-2020-12 nullable shorthand — `"type": ["array",
// "null"]` — for slice fields. ogen models a schema's `type` as a scalar
// and rejects the union form. The server is moving to non-nullable arrays
// (an absent collection serialises as `[]`, never `null`), so collapsing
// `["array","null"]` to `"array"` here matches the intended wire contract
// rather than papering over it. Once the server stops emitting the null
// member this pass finds nothing to change and is a no-op.
//
// Run via `go generate ./internal/coreapi/...` (the first generate step in
// gen.go), or by hand after refreshing the spec:
//
//	go run spec/normalize.go
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
)

const specPath = "spec/core.openapi.json"

func main() {
	if err := run(); err != nil {
		fmt.Fprintf(os.Stderr, "normalize: %v\n", err)
		os.Exit(1)
	}
}

func run() error {
	raw, err := os.ReadFile(specPath)
	if err != nil {
		return fmt.Errorf("read spec: %w", err)
	}

	var doc any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return fmt.Errorf("parse spec: %w", err)
	}

	changed := collapseTypeUnions(doc)

	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetIndent("", "  ")
	enc.SetEscapeHTML(false)
	if err := enc.Encode(doc); err != nil {
		return fmt.Errorf("encode spec: %w", err)
	}
	if err := os.WriteFile(specPath, buf.Bytes(), 0o644); err != nil { //nolint:gosec // spec is not a secret
		return fmt.Errorf("write spec: %w", err)
	}

	fmt.Printf("normalize: collapsed %d type-union(s) to scalar type\n", changed)
	return nil
}

// collapseTypeUnions walks the decoded JSON document and rewrites every
// schema object whose "type" is a JSON array containing "null" (e.g.
// ["array","null"]) to the bare non-null type ("array"). Returns the
// number of sites rewritten.
func collapseTypeUnions(node any) int {
	switch v := node.(type) {
	case map[string]any:
		count := 0
		if t, ok := v["type"].([]any); ok {
			if scalar, replaced := nonNullType(t); replaced {
				v["type"] = scalar
				count++
			}
		}
		for _, child := range v {
			count += collapseTypeUnions(child)
		}
		return count
	case []any:
		count := 0
		for _, child := range v {
			count += collapseTypeUnions(child)
		}
		return count
	default:
		return 0
	}
}

// nonNullType returns the single non-"null" member of a JSON-Schema type
// union and true when the union has exactly one non-null member (the only
// shape huma emits). Unions with zero or multiple non-null members are
// left untouched so a genuinely polymorphic type isn't silently flattened.
func nonNullType(types []any) (string, bool) {
	var nonNull []string
	for _, t := range types {
		s, ok := t.(string)
		if !ok {
			return "", false
		}
		if s != "null" {
			nonNull = append(nonNull, s)
		}
	}
	if len(nonNull) != 1 || len(types) == len(nonNull) {
		return "", false
	}
	return nonNull[0], true
}

