	return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
		item, err := fn(ctx, c)
		if err != nil {
			return err
		}
		if jsonRequested(cmd) {
			return printJSON(cmd.OutOrStdout(), item)
		}
		return printFields(cmd.OutOrStdout(), headers, row(*item))
	})
