// ClusterPublicHost resolves a cluster slug within this server's
// jurisdiction to the host portion of its public URL. Used by coreapi's
// MirrorService to translate the {mirrorId} path param back into the
// cluster_host string DeleteMirrorPlacement expects. Returns ("", nil)
// when the cluster store isn't wired or the slug is unknown — caller
// should fall back to the slug (dev paths) or surface a 503/404.
func (s *Server) ClusterPublicHost(ctx context.Context, slug string) (string, error) {
	if s.cluster == nil {
		return "", nil
	}
	c, err := s.cluster.GetBySlug(ctx, s.jurisdiction, slug)
	if err != nil {
		return "", fmt.Errorf("resolve cluster by slug: %w", err)
	}
	if c.PublicURL == "" {
		return "", nil
	}
	u, err := url.Parse(c.PublicURL)
	if err != nil {
		return "", fmt.Errorf("parse cluster public url: %w", err)
	}
	return u.Host, nil
}

// MirrorReposListAll exposes mirrorrepo.ListAll for visibility-
// filtering List implementations in coreapi.
func (s *Server) MirrorReposListAll(ctx context.Context, jurisdiction string) ([]MirrorListRow, error) {
	if s.mirrorRepos == nil {
		return nil, nil
	}
	rows, err := s.mirrorRepos.ListAll(ctx, jurisdiction)
	if err != nil {
		return nil, fmt.Errorf("mirrorrepo list-all: %w", err)
	}
	return wrapMirrorListRows(rows), nil
}

// FindMirrorByCoords resolves upstream mirror coords (provider, owner,
// repo) plus a jurisdiction to a single mirror repo ID, reading the
// mirror_repos source of truth via mirrorrepo.FindPlacements — the same
// table 'mirror create' writes and the internal repo-lookup RPC already
// reads. Backs the public by-mirror lookup endpoint. Returns ok=false
// when no mirror matches the pinned jurisdiction. An unsupported
// provider resolves to ok=false rather than an error so the endpoint
// stays an enumeration-safe 404.
func (s *Server) FindMirrorByCoords(ctx context.Context, provider, owner, repo, jurisdiction string) (model.RepoID, bool, error) {
	if s.mirrorRepos == nil {
		return model.RepoID{}, false, nil
	}
	if provider != mirrorrepo.ProviderGitHub {
		return model.RepoID{}, false, nil
	}
	placements, err := s.mirrorRepos.FindPlacements(ctx, provider, owner, repo)
	if err != nil {
		return model.RepoID{}, false, fmt.Errorf("mirrorrepo find-placements: %w", err)
	}
	for _, p := range placements {
		if p.Jurisdiction == jurisdiction {
			return p.MirrorRepoID, true, nil
		}
	}
	return model.RepoID{}, false, nil
}

// MirrorReposListURLs exposes mirrorrepo.ListURLs so coreapi can read a
// mirror's git URLs from github_mirror_repo_urls. Mirror repos have no
// repo_registry row, so resource.ListRepoURLs can't serve them.
func (s *Server) MirrorReposListURLs(ctx context.Context, id model.RepoID) ([]string, error) {
	if s.mirrorRepos == nil {
		return nil, nil
	}
	urls, err := s.mirrorRepos.ListURLs(ctx, id)
	if err != nil {
		return nil, fmt.Errorf("mirrorrepo list-urls: %w", err)
	}
	return urls, nil
}

// AccountCanPushUpstream reports whether accountID's linked GitHub user
// holds write+ (push) on the upstream owner/repo — the authority mirror
// teardown runs on (DeleteMirrorPlacement gates on githubPerms.CanPush).
// Mirror repos carry no SpiceDB user grants, so mirror authz is a
// GitHub-perms decision, not a repo#pull tuple. The by-mirror lookup uses
// this so its gate matches the delete it precedes exactly; without it the
// lookup 404'd for every operator before the delete could run.
//
// It's a point query on the upstream coords (not a jurisdiction-wide
// mirror scan) and deliberately ignores the mirror's suspension state:
// removal authority is about who can write the upstream, not whether the
