			}
			fmt.Fprint(out, ".")
		}
		select {
		case <-ctx.Done():
			fmt.Fprintln(out)
			return fmt.Errorf("timed out waiting for initial clone: %w", ctx.Err())
		case <-time.After(2 * time.Second):
		}
	}
}

