	if err := sr.Decode(resp.Body); err != nil {
		return false, 0
	}
	var adv packp.AdvRefs
	if err := adv.Decode(resp.Body); err != nil {
		return false, 0
	}
	if _, err := adv.ResolvedHead(); err != nil {
		return false, http.StatusOK // reachable, clone still in progress
	}
