package main

import (
	"context"
	"fmt"
	"os"

	"github.com/entireio/cli/internal/coreapi"
)

// Throwaway: confirms the by-mirror lookup's repoId equals the mirror's
// mirrorId from list, validating that DeleteMirror(repoId) is correct.
func main() {
	c, err := coreapi.New()
	if err != nil {
		fmt.Fprintln(os.Stderr, "client:", err)
		os.Exit(1)
	}
	ctx := context.Background()

	list, err := c.ListMirrors(ctx, coreapi.ListMirrorsParams{})
	if err != nil {
		fmt.Fprintln(os.Stderr, "list:", err)
		os.Exit(1)
	}
	mirrors := list.Response.Mirrors
	if len(mirrors) == 0 {
		fmt.Fprintln(os.Stderr, "no mirrors to check")
		os.Exit(1)
	}
